UPDATE acc_training_slides SET interactive_config = '{"type":"scenario","instruction":"You need to add a range check for Heart Rate (30-220 bpm) on a Vital Signs form. What is the fastest method?","data":{"context":"You are configuring validation for a new Vital Signs CRF. Heart Rate needs a range check.","choices":[{"text":"Open the Custom Rule Builder wizard and configure from scratch","correct":false,"feedback":"This works but is slower. Quick Add has a pre-built Heart Rate template."},{"text":"Click Quick Add → Vital Signs → Heart Rate 30-220 bpm","correct":true,"feedback":"Correct! Quick Add has preset templates for common vital signs ranges. One click, pick the field, done."},{"text":"Ask the AI Suggester to recommend a rule","correct":false,"feedback":"AI Suggester works but Quick Add is faster for standard vital sign ranges that have exact templates."},{"text":"Write a custom regex pattern","correct":false,"feedback":"Regex is for text format validation, not numeric ranges. Use Quick Add for number ranges."}]},"successMessage":"Quick Add is the fastest path for standard clinical value ranges!"}'
WHERE course_id = 7 AND order_index = 4;

UPDATE acc_training_slides SET interactive_config = '{"type":"scenario","instruction":"A Systolic BP field can realistically range from 60-250 mmHg. Values outside this are unusual but medically possible (shock, hypertensive crisis). Which severity should you choose?","data":{"context":"You are creating a validation rule for Systolic Blood Pressure. Normal range is 90-140, but values 60-250 are medically possible in extreme cases.","choices":[{"text":"Block Save — prevent form submission for any value outside 60-250","correct":false,"feedback":"Block Save prevents data entry of real clinical values. A patient in hypertensive crisis (SBP=260) would be unable to have their data recorded."},{"text":"Create Query — allow save but flag values outside 90-140 for review","correct":true,"feedback":"Correct! Use Create Query for clinically unusual but possible values. This flags them for review without blocking legitimate data entry."},{"text":"No validation needed — any BP value should be accepted","correct":false,"feedback":"No validation means typos like 6000 mmHg would go undetected. Always add range checks for clinical values."},{"text":"Block Save for anything outside 90-140","correct":false,"feedback":"90-140 is normal range, not physiological limits. Blocking save at 141 would prevent recording data for any hypertensive patient."}]},"successMessage":"Create Query is correct for clinically unusual but possible values!"}'
WHERE course_id = 7 AND order_index = 9;

